               return isTrueLiteral(((UReturnExpression) body).getReturnExpression());
           } else if (body instanceof ULiteralExpression) {
               return isTrueLiteral(body);
           }
           return false;
       }

       private static boolean isTrueLiteral(UExpression expr) {
           return expr instanceof ULiteralExpression && Boolean.TRUE.equals(((ULiteralExpression) expr).getValue());
       }
   }
